using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static partial class ForestSeatingAuthoring {
  const string DensityRequest="Logs/Forest638.request",DensityLogs="Logs/Forest638",DensityPrefix="pinefall-tree-hills200-";
  [InitializeOnLoadMethod]static void Register638(){EditorApplication.update+=Pending638;}
  static void Pending638(){if(!File.Exists(DensityRequest))return;if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete(DensityRequest);try{Apply638();}catch(Exception e){Directory.CreateDirectory(DensityLogs);File.WriteAllText(DensityLogs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static void TuneForest(GameObject root){var v=root.GetComponent<DistanceVisibility>();Require(v&&v.distantParts.Length==1,"missing cards");v.distance=200;v.distantDistance=2000;v.switchBuffer=12;foreach(var r in v.distantParts){r.gameObject.layer=11;PrefabUtility.RecordPrefabInstancePropertyModifications(r.gameObject);}EditorUtility.SetDirty(v);PrefabUtility.RecordPrefabInstancePropertyModifications(v);}
  public static void ForestCamera(Scene scene){
   var tags=new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);var l=tags.FindProperty("layers").GetArrayElementAtIndex(11);Require(string.IsNullOrEmpty(l.stringValue)||l.stringValue=="ForestCards","layer 11 occupied");l.stringValue="ForestCards";tags.ApplyModifiedProperties();
   foreach(var rig in All<CameraRig>(scene)){var policy=rig.view.GetComponent<CloudCameraVisibility>();Require(policy&&policy.layerDistances.Length==32,"missing camera policy");policy.layerDistances[11]=2000;rig.view.cullingMask|=1<<11;policy.Apply();EditorUtility.SetDirty(policy);EditorUtility.SetDirty(rig.view);}
  }
  [MenuItem("Snowglow/Environment/Apply 330m forest and add 200 hillside trees")]
  public static void Apply638(){
   if(All<CatalogPlacement>(SceneManager.GetActiveScene()).Count(Tree)==500){Apply500();return;}
   var scene=SceneManager.GetActiveScene();Require(scene.path==SceneValidation.ScenePath&&!EditorApplication.isPlayingOrWillChangePlaymode,"open Pinefall stopped");Directory.CreateDirectory(DensityLogs);if(!File.Exists(DensityLogs+"/Pinefall-before.unity"))Require(EditorSceneManager.SaveScene(scene,DensityLogs+"/Pinefall-before.unity",true),"backup");if(scene.isDirty)EditorSceneManager.SaveScene(scene,DensityLogs+"/Pinefall-unsaved-before.unity",true);cache.Clear();outerIds.Clear();slopeIds.Clear();
   var forest=All<CatalogPlacement>(scene).Where(Tree).OrderBy(p=>p.placementId).ToArray();Require(forest.Length==438||forest.Length==638,"expected 438 or completed 638 placements");var terrain=All<Terrain>(scene).Single();var session=All<PrototypeSession>(scene).Single();string snow=SnowData(session.Snow.seed);
   var protectedPaths=All<MeshFilter>(scene).Where(f=>f.sharedMesh).Select(f=>AssetDatabase.GetAssetPath(f.sharedMesh)).Concat(new[]{AssetDatabase.GetAssetPath(terrain.terrainData),AssetDatabase.GetAssetPath(session.Snow.seed)}).Where(p=>p.StartsWith("Assets/")).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));
   var scenery=All<CatalogPlacement>(scene).Where(p=>!Tree(p)&&!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,FullPose);var fleet=session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R")).ToArray();
   var mountains=All<CatalogPlacement>(scene).Where(Mountain).Select(p=>{var rs=p.GetComponentsInChildren<Renderer>(true);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}).ToArray();
   var obstacles=All<Collider>(scene).Where(c=>c.enabled&&c.gameObject.activeInHierarchy&&!c.isTrigger&&!(c is TerrainCollider)&&!(c is MeshCollider&&c.GetComponentInParent<SnowField>())&&!Tree(c.GetComponentInParent<CatalogPlacement>())).Select(c=>c.bounds).ToArray();
   var oldBounds=forest.SelectMany(p=>p.GetComponentsInChildren<Collider>(true)).Select(c=>c.bounds).ToArray();var rng=new System.Random(8330638);var plans=new List<Plan>();var occupied=new List<Occupied>();
   var relocate=forest.Where(p=>new Vector2(p.transform.position.x,p.transform.position.z).magnitude>ForestRadius||!VisibleGround(WorldBounds(Data(p.assetId),p.transform.position,p.transform.rotation,p.transform.lossyScale),mountains)).ToArray();
   foreach(var p in forest.Except(relocate))occupied.Add(new Occupied{id=p.placementId,point=p.transform.position,radius=Radius(Data(p.assetId),p.transform.lossyScale)});
   foreach(var p in relocate){var plan=Find(Data(p.assetId),terrain,p.transform.position,Yaw(p.transform.rotation),p.transform.lossyScale,mountains,obstacles,occupied,rng,p.placementId,p);plans.Add(plan);occupied.Add(new Occupied{id=plan.id,point=plan.position,radius=Radius(plan.geometry,plan.scale)});}
   var candidates=new List<Vector3>[] {new List<Vector3>(),new List<Vector3>()};for(int z=-324;z<=324;z+=4)for(int x=-324;x<=324;x+=4){var p=new Vector3(x,0,z);if(new Vector2(x,z).magnitude>325||Mathf.Abs(x)<140&&Mathf.Abs(z)<140)continue;int band=HillBand(terrain,p);if(band<2)candidates[band].Add(p);}
   var variants=forest.Where(p=>!Data(p.assetId).wood).Select(p=>p.assetId).ToArray();int added=638-forest.Length;
   for(int i=0;i<added;i++){var d=Data(variants[rng.Next(variants.Length)]);int band=i<120?0:1;Plan plan=null;for(int attempt=0;attempt<60000;attempt++){if(attempt==15000)band=1-band;if(attempt>0&&attempt%500==0)d=Data(variants[rng.Next(variants.Length)]);var p=candidates[band][rng.Next(candidates[band].Count)]+new Vector3((float)rng.NextDouble()*4-2,0,(float)rng.NextDouble()*4-2);if(HillBand(terrain,p)!=band)continue;var scale=Vector3.one*(.8f+(float)rng.NextDouble()*.6f);if(!Spaced(d,p,scale,occupied)||!Fit(d,terrain,p,(float)rng.NextDouble()*360,scale,mountains,obstacles,out var pos,out var rot))continue;plan=new Plan{geometry=d,id=DensityPrefix+(i+1).ToString("D3"),position=pos,rotation=rot,scale=scale};break;}Require(plan!=null,"no hillside site for addition "+i+"; relocated "+relocate.Length);plans.Add(plan);occupied.Add(new Occupied{id=plan.id,point=plan.position,radius=Radius(d,plan.scale)});}
   // Plan all placement changes before modifying scene or prepared prefabs.
   ForestCamera(scene);
   foreach(var a in forest.Select(p=>p.assetId).Distinct().Select(id=>CatalogPreparation.Library().Find(id))){var path=AssetDatabase.GetAssetPath(a.prefab);var root=PrefabUtility.LoadPrefabContents(path);try{TuneForest(root);PrefabUtility.SaveAsPrefabAsset(root,path);a.assumptions=a.assumptions.Replace("230m","200m").Replace("650m","2000m");EditorUtility.SetDirty(a);}finally{PrefabUtility.UnloadPrefabContents(root);}}
   foreach(var plan in plans){var p=plan.existing;if(!p){var go=(GameObject)PrefabUtility.InstantiatePrefab(plan.geometry.asset.prefab,scene);go.transform.SetParent(forest[0].transform.parent,true);p=go.GetComponent<CatalogPlacement>();p.placementId=plan.id;PrefabUtility.RecordPrefabInstancePropertyModifications(p);}p.transform.localScale=plan.scale;p.transform.SetPositionAndRotation(plan.position,plan.rotation);PrefabUtility.RecordPrefabInstancePropertyModifications(p.transform);}
   var current=All<CatalogPlacement>(scene).Where(Tree).ToArray();foreach(var p in current)TuneForest(p.gameObject);Physics.SyncTransforms();Validate638(current,terrain,mountains);int mask=RefreshMask(session.Snow,oldBounds,current.SelectMany(p=>p.GetComponentsInChildren<Collider>(true)).Select(c=>c.bounds).ToArray());Require(snow==SnowData(session.Snow.seed),"snow quantity change");SceneValidation.Validate(scene);MechanicsChecks.Run();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Require(EditorSceneManager.SaveScene(scene),"save failed");scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);current=All<CatalogPlacement>(scene).Where(Tree).ToArray();foreach(var rig in All<CameraRig>(scene))Require(rig.view.layerCullDistances[11]==2000&&rig.view.farClipPlane>=2000&&(rig.view.cullingMask&(1<<11))!=0,"saved camera card limit");Validate638(current,All<Terrain>(scene).Single(),mountains);SceneValidation.Validate(scene);MechanicsChecks.Run();session=All<PrototypeSession>(scene).Single();Require(snow==SnowData(session.Snow.seed),"saved snow quantities");foreach(var p in All<CatalogPlacement>(scene).Where(p=>scenery.ContainsKey(p.placementId??"")))Require(scenery[p.placementId]==FullPose(p),"nonforest pose changed");Require(fleet.SequenceEqual(session.Fleet.Select(m=>m.transform.localToWorldMatrix.ToString("R"))),"fleet moved");foreach(var pair in protectedPaths)Require(pair.Value==AssetDatabase.GetAssetDependencyHash(pair.Key),"source changed "+pair.Key);
   File.WriteAllText(DensityLogs+"/Placements.csv","id,variant,band,x,y,z\n"+string.Join("\n",current.Select(p=>p.placementId+","+p.assetId+","+BandName(HillBand(All<Terrain>(scene).Single(),p.transform.position))+","+p.transform.position.x+","+p.transform.position.y+","+p.transform.position.z)));
   File.WriteAllText(DensityLogs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+". Saved/reopened 638 forest placements; 200 addition IDs verified, "+added+" trees newly placed this pass (hill/slope-only sites, hills preferred); relocated "+relocate.Length+" existing placements inside 330m full-bound radius. Nominal camera switch 200m, hysteresis 188/212m, cards 2000m on dedicated layer11, other camera layer limits retained. Terrain seating, mountain exclusion, LOD3, solid collision, new-tree hill/slope classification, near/far/cull tests, scene validation and 19 snow checks passed. Source mesh/Terrain/original seed hashes, snow quantities, fleet and nonforest poses preserved. Obstacle flag changes "+mask+". No runtime spawning, district rebake or player-save writes. Live Play and phone performance untested.");ForestCardsSceneReview.Run();
  }
  static void Validate638(CatalogPlacement[] forest,Terrain terrain,Bounds[] mountains){Validate(forest,terrain,mountains,638);Require(forest.Count(p=>(p.placementId??"").StartsWith(DensityPrefix))==200,"200 additions missing");foreach(var p in forest){var v=p.GetComponent<DistanceVisibility>();Require(v.distance==200&&v.distantDistance==2000&&v.distantParts.All(r=>r.gameObject.layer==11),"visibility policy");Require(p.GetComponentsInChildren<Collider>(true).Count(c=>c.enabled&&!c.isTrigger)==1,"solid box");if((p.placementId??"").StartsWith(DensityPrefix))Require(!Data(p.assetId).wood&&HillBand(terrain,p.transform.position)<2,"new tree outside hills/slopes");}var source=forest[0];var go=UnityEngine.Object.Instantiate(source.gameObject);try{var v=go.GetComponent<DistanceVisibility>();var p=go.transform.position;v.Evaluate(p+Vector3.right*100);Require(v.ShowingGeometry,"near");v.Evaluate(p+Vector3.right*213);Require(!v.ShowingGeometry&&v.distantParts.All(r=>r.enabled),"card switch");v.Evaluate(p+Vector3.right*1900);Require(v.distantParts.All(r=>r.enabled),"1900m visibility");v.Evaluate(p+Vector3.right*2001);Require(v.distantParts.Concat(v.nearParts).All(r=>!r.enabled),"2km cutoff");v.Evaluate(p+Vector3.right*187);Require(v.ShowingGeometry,"return near");}finally{UnityEngine.Object.DestroyImmediate(go);}}
 }
